<template>
  <section class="rd-tasks">
    <header class="rd-page-header"><div><p class="rd-eyebrow">RD STUDIO</p><h1>{{ adminView ? '任务管理' : '任务中心' }}</h1></div><a v-if="!adminView" class="rd-button" href="/activity/"><Trophy :size="16" />每周活跃榜</a><a v-if="me?.role === 'admin'" class="rd-button" :href="adminView ? '/tasks' : '/admin/tasks'"><ShieldCheck :size="16" />{{ adminView ? '任务中心' : '管理任务' }}</a></header>
    <PageState v-if="loading" kind="loading" title="正在加载任务" />
    <PageState v-else-if="unauthorized" title="登录后查看任务"><a class="rd-button rd-button-primary" href="/login">登录</a></PageState>
    <PageState v-else-if="fatal" kind="error" title="暂时无法加载" :message="fatal"><button class="rd-button" @click="load"><RotateCw :size="16" />重试</button></PageState>
    <template v-else-if="me">
      <div v-if="error" class="task-notice" role="alert">{{ error }}</div><div v-if="message" class="task-notice" role="status">{{ message }}</div>
      <nav v-if="adminView" class="task-admin-nav rd-segments" aria-label="任务管理视图"><button v-for="tab in adminTabs" :key="tab.id" :aria-pressed="view === tab.id" :disabled="busy" @click="view = tab.id">{{ tab.label }}</button></nav>
      <template v-if="!adminView">
        <section class="task-identity" aria-label="经验与专业"><div><strong class="rank-badge" :class="rankClass(me.level,me.identity.office)">{{ me.identity.office==='president' ? '会长' : me.level.title }}</strong><span v-if="me.identity.office">{{ officeNames[me.identity.office] }}</span><p>{{ me.xp }} EXP<template v-if="me.next_level"> · 距离{{ me.next_level.title }}还需 {{ me.next_level.threshold - me.xp }} EXP</template></p><progress v-if="me.next_level" :value="me.xp-me.level.threshold" :max="me.next_level.threshold-me.level.threshold" aria-label="升级进度"></progress></div><label>专业分支<select :value="me.identity.discipline_id || ''" :disabled="busy" @change="saveDiscipline($event.target.value)"><option value="">未选择</option><option v-for="d in me.disciplines" :key="d.id" :value="d.id">{{ d.name }}</option></select></label></section>
        <div class="task-filter rd-segments" role="group" aria-label="任务筛选"><button v-for="tab in memberTabs" :key="tab.id" :aria-pressed="filter === tab.id" :disabled="busy" @click="filter=tab.id">{{ tab.label }}</button><button class="task-refresh" aria-label="刷新进度" title="刷新进度" :disabled="busy" @click="action(refresh,'')"><RotateCw :size="17" /></button></div>
      </template>
      <template v-if="!adminView || view === 'tasks'">
        <form v-if="adminView" class="task-create" @submit.prevent="createTask">
          <h2>新建任务</h2>
          <div class="task-form-grid">
            <label>标题<input v-model="form.title" maxlength="120" required></label>
            <label>模板<select v-model="form.type"><option value="publish">发布帖子</option><option value="read">浏览帖子（每篇 3 分钟）</option><option value="branch">创建知识库分支</option><option value="gamejam">参加 Game Jam</option><option value="proof">自定义证明任务</option></select></label>
            <label v-if="automatic(form.type)">目标数量<input v-model.number="form.target" type="number" min="1" max="1000" required></label>
            <label>经验奖励<input v-model.number="form.reward" :disabled="form.is_advanced" type="number" min="1" max="10000" required></label>
            <label>截止时间<input v-model="form.deadline" type="datetime-local" :required="Boolean(form.audience)"></label>
            <label><input v-model="form.is_advanced" type="checkbox" @change="form.is_advanced && (form.reward=100)">进阶任务（50 EXP 解锁）</label>
          </div>
          <label class="task-description-field">任务说明<textarea v-model="form.description" rows="3" maxlength="6000"></textarea></label>
          <fieldset v-if="!automatic(form.type)" class="task-requirements"><legend>证明要求</legend><label v-for="r in requirementOptions" :key="r.id"><input v-model="form.requirements[r.id]" type="checkbox" :disabled="form.type === 'gamejam' && r.id === 'url'">{{ r.label }}</label></fieldset>
          <TaskAudiencePicker v-model="form.audience" :levels="me.levels" :disciplines="me.disciplines" :disabled="busy" />
          <button class="rd-button rd-button-primary" :disabled="busy"><Plus :size="16" />保存草稿</button>
        </form>
        <div v-if="adminView && tasks.some(t=>t.assigned)" class="task-meta"><p v-for="task in tasks.filter(t=>t.assigned)" :key="task.id">{{ task.title }} · {{ task.status==='draft' ? '定向派发草稿' : '已派发 '+task.recipient_count+' 人' }}</p></div>
        <PageState v-if="!visibleTasks.length" title="暂无任务" />
        <DailyTasks v-if="!adminView" />
        <div class="task-list"><article v-for="task in visibleTasks" :key="task.id" class="task-item"><div class="task-item-heading"><span class="task-type">{{ typeNames[task.type] }}</span><span class="task-reward">+{{ task.reward }} EXP</span></div><h2>{{ task.title }}</h2><p class="task-description">{{ task.description }}</p><div class="task-meta"><span>{{ statusNames[task.status] }}</span><span v-if="task.deadline">截止 {{ date(task.deadline) }}</span><span v-if="!automatic(task.type)">{{ requiredText(task) }}</span></div><template v-if="task.enrollment"><div class="task-progress"><progress v-if="automatic(task.type)" :value="task.progress" :max="task.target" :aria-label="task.title + '进度'"></progress><span>{{ stateNames[task.enrollment.state] }}<template v-if="automatic(task.type)"> · {{ task.progress }} / {{ task.target }}</template></span></div><p v-if="task.submission?.review_note" class="task-review-note">审核意见：{{ task.submission.review_note }}</p></template><div class="task-item-actions"><template v-if="adminView"><button v-if="task.status !== 'active' && !expired(task)" class="rd-button" :disabled="busy" @click="setStatus(task,'active')"><Send :size="16" />{{ task.status === 'draft' ? '发布' : '重新开放' }}</button><button v-if="task.status === 'active'" class="rd-button" :disabled="busy" @click="setStatus(task,'closed')">关闭任务</button></template><template v-else-if="task.status === 'active' && !expired(task)"><button v-if="!task.enrollment" class="rd-button rd-button-primary" :disabled="busy" @click="join(task)">领取任务</button><button v-else-if="automatic(task.type) && task.enrollment.state === 'joined'" class="rd-button" :disabled="busy || task.progress < task.target" @click="claim(task)"><Check :size="16" />领取奖励</button><button v-else-if="!automatic(task.type) && ['joined','rejected'].includes(task.enrollment.state)" class="rd-button" :disabled="busy" @click="openProof(task)"><Upload :size="16" />提交证明</button></template><span v-if="expired(task)" class="task-meta">已截止</span></div></article></div>
        <nav v-if="hasMore || offset" class="rd-pagination" aria-label="任务分页"><button class="rd-button" :disabled="busy || !offset" @click="turnPage(-30)">上一页</button><span>{{ offset / 30 + 1 }}</span><button class="rd-button" :disabled="busy || !hasMore" @click="turnPage(30)">下一页</button></nav>
        <section v-if="!adminView" class="task-ledger"><h2>经验记录</h2><p v-if="!me.ledger.length" class="task-meta">暂无经验记录</p><div v-for="row in me.ledger" :key="row.id" class="task-ledger-row"><span>{{ row.reason }}<small>{{ date(row.created_at) }}</small></span><strong>{{ row.amount>0 ? '+' : '' }}{{ row.amount }} EXP</strong></div></section>
      </template>
      <section v-else-if="view === 'reviews'" class="task-review-list"><h2>证明审核</h2><PageState v-if="!reviews.length" title="暂无证明提交" /><article v-for="row in reviews" :key="row.id" class="task-item"><div class="task-item-heading"><h3>{{ row.title }}</h3><span>{{ reviewNames[row.status] }}</span></div><p class="task-meta">{{ row.username }} · {{ date(row.submitted_at) }}</p><p class="task-description">{{ row.note }}</p><a v-if="row.url" :href="row.url" target="_blank" rel="noopener noreferrer" class="task-proof-link">{{ row.url }}</a><div class="task-files"><a v-for="file in row.files" :key="file.id" :href="file.url" target="_blank" rel="noopener noreferrer">{{ file.missing ? '文件不可用' : file.path.split('/').at(-1) }}</a></div><template v-if="row.status === 'pending'"><label>审核意见<textarea v-model="reviewNotes[row.id]" maxlength="1000" rows="2"></textarea></label><div class="task-item-actions"><button class="rd-button rd-button-primary" :disabled="busy" @click="review(row,true)"><Check :size="16" />通过并发经验</button><button class="rd-button" :disabled="busy" @click="review(row,false)"><X :size="16" />拒绝</button></div></template><p v-else class="task-meta">{{ row.review_note }}</p></article><nav v-if="reviewHasMore || reviewOffset" class="rd-pagination" aria-label="审核分页"><button class="rd-button" :disabled="busy || !reviewOffset" @click="turnReviews(-30)">上一页</button><button class="rd-button" :disabled="busy || !reviewHasMore" @click="turnReviews(30)">下一页</button></nav><h2>近期奖励</h2><div v-for="row in rewards" :key="row.id" class="task-ledger-row"><span>{{ row.username }} · {{ row.title }} · +{{ row.amount }} EXP</span><span>已发放</span></div></section>
      <section v-else-if="view === 'people'"><h2>社员职位</h2><form class="task-people-search" @submit.prevent="findPeople"><label>社员名称<input v-model="peopleSearch" maxlength="100"></label><button class="rd-button" :disabled="busy"><Search :size="16" />搜索</button></form><div v-for="person in people" :key="person.id" class="task-ledger-row"><span>{{ person.username }}<small>{{ person.xp }} EXP · <b class="rank-badge" :class="rankClass(person.level,person.office)">{{person.office==='president'?'会长':person.level.title}}</b></small></span><label>职位<select :value="person.office || ''" :disabled="busy" @change="setOffice(person,$event.target.value)"><option value="">无任命</option><option value="president">会长</option><option value="vice-president">副会长</option></select></label></div></section>
      <form v-else-if="view === 'levels'" class="task-levels" @submit.prevent="saveLevels"><h2>经验等级门槛</h2><div v-for="(level,index) in levels" :key="index" class="task-form-grid"><label>称号<input v-model="level.title" maxlength="30" required></label><label>累计经验<input v-model.number="level.threshold" type="number" min="0" max="100000000" :disabled="index===0" required></label></div><button class="rd-button rd-button-primary" :disabled="busy"><Save :size="16" />保存等级</button></form>
    </template>
    <dialog ref="proofDialog" class="task-dialog" @close="proofTask = null" @cancel="cancelProof"><form @submit.prevent="submitProof"><div class="task-item-heading"><h2>{{ proofTask?.title }}</h2><button type="button" class="task-icon-button" aria-label="关闭提交窗口" title="关闭" :disabled="busy" @click="closeProof"><X :size="20" /></button></div><p v-if="proofError" role="alert" class="task-notice">{{ proofError }}</p><label>完成说明<textarea v-model="proof.note" rows="4" maxlength="4000" required></textarea></label><label>参赛或作品网址<input v-model="proof.url" type="url" placeholder="https://" maxlength="2000" :required="proofTask?.requirements.url"></label><label>证明图片或作品文件<input ref="fileInput" type="file" multiple :disabled="busy" @change="selectFiles"></label><ul class="task-selected-files"><li v-for="(file,index) in proof.files" :key="file.id">{{ file.name }}<button type="button" class="task-icon-button" :aria-label="'移除 '+file.name" :disabled="busy" @click="removeFile(index)"><X :size="15" /></button></li></ul><button class="rd-button rd-button-primary" :disabled="busy"><Upload :size="16" />{{ busy ? '处理中...' : '提交审核' }}</button></form></dialog>
  </section>
</template>
<script setup>
import { computed, nextTick, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { Check, Plus, RotateCw, Save, Search, Send, ShieldCheck, Trophy, Upload, X } from 'lucide-vue-next'
import PageState from './PageState.vue'
import DailyTasks from './DailyTasks.vue'
import TaskAudiencePicker from './TaskAudiencePicker.vue'
import { rankClass } from '../lib/community-api.mjs'
import { taskRequest, uploadTaskEvidence, removeTaskEvidence } from '../lib/task-api.mjs'
const props = defineProps({ adminView: Boolean })
const me=ref(null), tasks=ref([]), loading=ref(true), unauthorized=ref(false), fatal=ref(''), error=ref(''), message=ref(''), busy=ref(false), view=ref('tasks'), filter=ref('all'), offset=ref(0), hasMore=ref(false)
const reviews=ref([]), rewards=ref([]), reviewNotes=reactive({}), reviewOffset=ref(0), reviewHasMore=ref(false), people=ref([]), peopleSearch=ref(''), levels=ref([])
const proofDialog=ref(null), proofTask=ref(null), fileInput=ref(null), proofError=ref(''), proof=reactive({note:'',url:'',files:[]})
const form=reactive({title:'',description:'',type:'publish',target:1,reward:100,is_advanced:false,deadline:'',requirements:{url:false,image:false,build:false}})
const typeNames={publish:'发布帖子',read:'浏览帖子 · 每篇 3 分钟',branch:'知识库分支',gamejam:'Game Jam',proof:'证明任务'}, statusNames={draft:'草稿',active:'开放中',closed:'已关闭'}, stateNames={joined:'进行中',submitted:'待审核',rejected:'需要重新提交',completed:'已完成',revoked:'奖励已撤销'}, reviewNames={pending:'待审核',approved:'已通过',rejected:'已拒绝'}, officeNames={president:'会长','vice-president':'副会长'}
const adminTabs=[{id:'tasks',label:'任务'},{id:'reviews',label:'证明审核'},{id:'people',label:'用户管理'},{id:'levels',label:'经验等级'}], memberTabs=[{id:'all',label:'全部'},{id:'mine',label:'我的任务'},{id:'completed',label:'已完成'}], requirementOptions=[{id:'url',label:'网址'},{id:'image',label:'图片'},{id:'build',label:'作品文件'}]
const automatic=type=>['publish','read','branch'].includes(type), expired=task=>task.deadline && task.deadline<Date.now(), date=time=>new Date(time).toLocaleString('zh-CN')
const visibleTasks=computed(()=>tasks.value.filter(t=>filter.value==='all'||(filter.value==='mine' ? t.enrollment : t.enrollment?.state==='completed')))
const requiredText=task=>requirementOptions.filter(r=>task.requirements[r.id]).map(r=>r.label).join(' · ')
let disposed=false, subscription, revision=0, loadRevision=0
async function refresh() { const request=++revision; const [identity,list]=await Promise.all([taskRequest('/me'),taskRequest('?offset='+offset.value+'&scope='+filter.value)]); if(disposed || request!==revision)return; me.value=identity; tasks.value=list.items;hasMore.value=list.has_more; levels.value=identity.levels.map(l=>({...l})) }
async function load() { const request=++loadRevision; loading.value=true; fatal.value=''; unauthorized.value=false; try { await refresh(); if(disposed || request!==loadRevision)return; if(props.adminView && me.value?.role!=='admin')throw new Error('需要管理员权限'); if(props.adminView)await loadReviews() } catch(e){ if(disposed || request!==loadRevision)return; if(e.status===401){me.value=null;tasks.value=[];unauthorized.value=true} else fatal.value=e.message } finally { if(!disposed && request===loadRevision)loading.value=false } }
async function action(fn,success='操作已完成') { if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn();await refresh();message.value=success;window.dispatchEvent(new CustomEvent('rd:task-updated'))}catch(e){error.value=e.message}finally{busy.value=false} }
const join=task=>action(()=>taskRequest('/'+task.id+'/join',{method:'POST',body:{}}),'已领取任务'), claim=task=>action(()=>taskRequest('/'+task.id+'/claim',{method:'POST',body:{}}),'经验奖励已到账')
const saveDiscipline=id=>action(()=>taskRequest('/identity',{method:'PUT',body:{discipline_id:id||null}}),'专业分支已更新')
const setStatus=(task,status)=>action(()=>taskRequest('/'+task.id+'/status',{method:'PATCH',body:{status}}),'任务状态已更新')
async function createTask(){ await action(async()=>{ if(form.audience && !form.deadline)throw new Error('派发任务必须填写截止时间');await taskRequest('',{method:'POST',body:{...form,deadline:form.deadline?new Date(form.deadline).getTime():null}});form.title='';form.description='';offset.value=0 },'任务草稿已保存') }
const turnPage=delta=>action(async()=>{offset.value+=delta;await refresh()},'')
async function loadReviews(){const result=await taskRequest('/reviews?offset='+reviewOffset.value);if(disposed)return;reviews.value=result.items;reviewHasMore.value=result.has_more;rewards.value=result.rewards}
const review=(row,approved)=>action(async()=>{await taskRequest('/reviews/'+row.id,{method:'POST',body:{approved,note:reviewNotes[row.id]||''}});await loadReviews()},approved?'审核通过，经验已发放':'已拒绝，可重新提交')
const turnReviews=delta=>action(async()=>{reviewOffset.value+=delta;await loadReviews()},'')
const findPeople=()=>action(async()=>{people.value=await taskRequest('/people?q='+encodeURIComponent(peopleSearch.value))},'')
const setOffice=(person,office)=>action(async()=>{await taskRequest('/people/'+person.id,{method:'PUT',body:{office:office||null}});await findPeopleRaw()},'职位已更新')
async function findPeopleRaw(){people.value=await taskRequest('/people?q='+encodeURIComponent(peopleSearch.value))}
const saveLevels=()=>action(()=>taskRequest('/levels',{method:'PUT',body:{levels:levels.value}}),'等级门槛已保存')
watch(view,async value=>{if(props.adminView){const url=new URL(location.href);url.searchParams.set('view',value);history.replaceState(history.state,'',url);window.dispatchEvent(new CustomEvent('rd:admin-navigation'))}if(value==='reviews')await action(loadReviews,'');if(value==='people')await action(findPeopleRaw,'')})
watch(filter,async()=>{offset.value=0;await action(refresh,'')})
watch(proofTask,(task,previous)=>{if(!task && previous)Promise.all(proof.files.filter(f=>f.unsubmitted).map(f=>removeTaskEvidence(f.path))).catch(e=>{error.value=e.message})})
watch(()=>form.type,type=>{if(type==='gamejam')form.requirements.url=true})
async function openProof(task){proofTask.value=task;proof.note=task.submission?.note||'';proof.url=task.submission?.url||'';proof.files=(task.submission?.files||[]).filter(f=>!f.missing).map(f=>({...f,name:f.path.split('/').at(-1)}));proofError.value='';if(fileInput.value)fileInput.value.value='';await nextTick();proofDialog.value.showModal()}
function closeProof(){if(!busy.value)proofDialog.value.close()}
function cancelProof(event){if(busy.value)event.preventDefault()}
async function selectFiles(event){if(busy.value)return;const selected=[...event.target.files];if(proof.files.length+selected.length>5){proofError.value='最多提交 5 个文件';return}busy.value=true;proofError.value='';try{for(const file of selected){if(file.size>100*1024*1024)throw new Error('每个文件不能超过 100MB');proof.files.push({...await uploadTaskEvidence(file,me.value.id),unsubmitted:true})}}catch(e){proofError.value=e.message}finally{busy.value=false;event.target.value=''}}
async function removeFile(index){const file=proof.files[index];busy.value=true;try{if(file.unsubmitted)await removeTaskEvidence(file.path);proof.files.splice(index,1)}catch(e){proofError.value=e.message}finally{busy.value=false}}
async function submitProof(){if(busy.value)return;busy.value=true;proofError.value='';try{await taskRequest('/'+proofTask.value.id+'/submit',{method:'POST',body:{note:proof.note,url:proof.url,files:proof.files.map(f=>f.id)}});proof.files.forEach(f=>{f.unsubmitted=false});proofDialog.value.close();await refresh();message.value='证明已提交，等待管理员审核'}catch(e){proofError.value=e.message}finally{busy.value=false}}
onMounted(()=>{const params=new URLSearchParams(location.search);const initial=params.get('view');if(props.adminView && adminTabs.some(t=>t.id===initial)){view.value=initial};if(!props.adminView && memberTabs.some(t=>t.id===params.get('scope')))filter.value=params.get('scope');window.addEventListener('rd:community-updated',load);load();subscription=window.__api?.auth.onAuthStateChange(event=>{if(event!=='INITIAL_SESSION'){++revision;proofDialog.value?.close();me.value=null;tasks.value=[];reviews.value=[];rewards.value=[];people.value=[];load()}}).data.subscription})
onUnmounted(()=>{window.removeEventListener('rd:community-updated',load);disposed=true;++revision;++loadRevision;subscription?.unsubscribe()})
</script>
